/* i18n.js — one panel, two languages.
 * (generated by `npm run i18n` — edit ui/i18n.en.json, ui/i18n.words.json and
 *  ui/i18n.connectors.json, then scripts/i18n-template.js if the logic changes.)
 *
 * The engine speaks Persian: job logs, stage labels and error banners are all
 * written in it, and the video it renders is Persian and right-to-left. This
 * file translates the *interface* into English when the reader's browser is not
 * Persian, without touching a single byte of the engine or of the captions.
 *
 * How it matches, in order:
 *   1. the whole text node or attribute against PHRASES — exact, so nothing is
 *      paraphrased by accident;
 *   2. otherwise word by word against WORDS — dynamic strings arrive already
 *      interpolated ("12 s, energy 60%"), so no static key can ever match them;
 *   3. function words (CONNECTORS) ride along, but only once a real term has
 *      matched, so a Persian sentence nobody translated stays Persian.
 *
 * Things that are *content*, not chrome, are left alone: input and textarea
 * values (the user's own copy), anything inside [data-no-i18n] (the beat
 * preview shows real card text), and code blocks (file paths are file paths).
 *
 * Locale comes from localStorage, then the browser; the choice is remembered.
 * Set `dir` on <html> so the whole layout mirrors with the language — the panel
 * is built on logical properties, so this is the only switch it needs.
 */
(() => {
  const KEY = 'studio.lang';
  const FA_DIGITS = '۰۱۲۳۴۵۶۷۸۹';

  /* Exact strings, straight from the sources — regenerate with
   * `npm run i18n` and translate what the coverage report lists. */
  const PHRASES = {
  "استودیو ویدیو": "Video Studio",
  "جاب جدید": "New job",
  "جاب‌ها": "Jobs",
  "رفرنس‌ها": "References",
  "تنظیمات": "Settings",
  "موتور روی این ماشین روشن نیست.": "The engine on this machine is not running.",
  "امتحان": "Try",
  "دو فایل بده — ویدیوی خودت و یک ویدیوی رفرنس — بقیه‌اش با ایجنتِ انتخابی خودت.": "Hand it two files — your video and a reference video — and your chosen agent does the rest.",
  "ایجنت": "Agent",
  "کی ادیت را انجام می‌دهد": "who does the edit",
  "ورودی‌ها": "Inputs",
  "ویدیوی من + رفرنس": "my video + a reference",
  "خروجی": "Output",
  "نسبت، کیفیت، صدا": "ratio, quality, sound",
  "شروع": "Launch",
  "مرور و اجرا": "Review & launch",
  "مرحلهٔ صفر — چه کسی ادیت کند؟": "Stage zero — who edits?",
  "مغز API": "API brain",
  "مراحل هوشمند (درک متن، سناریو) با مدل انتخابی اجرا می‌شود؛ رندر همیشه محلی است.": "The smart stages (understanding, scenario) run on your chosen model; rendering always stays local.",
  "کلید هست": "key saved",
  "کلید لازم": "key needed",
  "خودِ استودیو (بدون مدل)": "The studio itself (no model)",
  "نصب است": "installed",
  "نصب نیست": "not installed",
  "مدل": "Model",
  "کلید API": "API key",
  "آدرس پایه": "Base URL",
  "پنل خودش پایپ‌لاین را اجرا می‌کند و فقط مراحل هوشمند را از مدل می‌پرسد.": "The panel runs the pipeline itself and only asks the model for the smart stages.",
  "بدون هیچ مدلی — همه‌چیز با قوانین قطعی خانه؛ برای تست و کارهای ساده.": "No model at all — everything follows the house's deterministic rules; good for tests and simple jobs.",
  "روی شروع، پنل همین ایجنت را headless روی جاب اجرا می‌کند (HANDOFF.md را می‌خواند و تا خروجی می‌رود).": "On launch the panel runs this agent headless on the job (it reads HANDOFF.md and drives it to the deliverable).",
  "نصب نیست — پنل دستور wake را می‌دهد تا خودت در ترمینال اجرایش کنی.": "Not installed — the panel shows a wake command for you to run in the terminal.",
  "دو فایل ورودی": "The two input files",
  "ویدیوی من": "My video",
  "همان فیلمی که باید ادیت شود.": "The film that gets edited.",
  "ویدیوی رفرنس": "Reference video",
  "سبک هدف — ریتم، ترنزیشن، پالت. یک بار تحلیل می‌شود و برای همیشه یاد می‌ماند.": "The target style — rhythm, transitions, palette. Analysed once, remembered forever.",
  "فایل را بکِش و رها کن، یا": "Drag & drop the file here, or",
  "از دیسک انتخاب کن": "pick from disk",
  "هیچ": "none",
  "لوگو (اختیاری)": "Logo (optional)",
  "خروجی نهایی": "Final output",
  "کیفیت": "Quality",
  "پیش‌نویس (سریع)": "Draft (fast)",
  "خوش‌دید (متوسط)": "Good look (medium)",
  "تحویل (تمیز)": "Delivery (clean)",
  "سقف حجم (مگابایت)": "Size budget (MB)",
  "صدا": "Sound",
  "بدون افکت": "no SFX",
  "ملایم": "gentle",
  "متعادل": "balanced",
  "پرقدرت": "bold",
  "نام جاب": "Job name",
  "بی‌نام می‌ماند اگر خالی بگذاری": "stays untitled if you leave it empty",
  "جهت‌دهی (اختیاری — این متن را مثل سند می‌خوانیم)": "Direction (optional — read like a brief)",
  "شروع جاب": "Start job",
  "قبلی": "Back",
  "بعدی": "Next",
  "در صف ایجنت": "Queued for the agent",
  "جابی باز نیست — از": "No job is open — pick one from",
  "یکی را باز کن یا جاب تازه‌ای بساز.": "or start a new one.",
  "لغو": "Cancel",
  "بستن": "Close",
  "در حال ساخت": "building",
  "منتظر بازبینی تو": "waiting for your review",
  "در صف ایجنت_status": "queued",
  "آماده": "ready",
  "خطا": "failed",
  "لغو شد": "cancelled",
  "ساخته نشده": "draft",
  "لاگ زنده": "Live log",
  "آرتیفکت‌ها": "Artifacts",
  "باز کن": "open",
  "بریف — ویدیو دربارهٔ چیست؟": "Brief — what is the video about?",
  "سناریو و استراتژی تدوین": "Scenario & edit strategy",
  "بازبینی ترنسکریپت": "Transcript review",
  "دروازهٔ ۱": "gate 1",
  "هر خط را می‌توانی ویرایش کنی — غلط املایی و اشتباه whisper را همین‌جا بگیر. وقت هر خط را که کلیک کنی ویدیو همان‌جا می‌پرد.": "Edit any line — catch typos and whisper mistakes here. Click a timestamp and the video jumps there.",
  "ذخیرهٔ اصلاحات": "Save corrections",
  "تایید و ادامه": "Approve & continue",
  "دموی اولیه": "First demo",
  "دروازهٔ ۲": "gate 2",
  "کم‌حجم و سریع است — فقط برای قضاوت دربارهٔ ادیت. هر تغییری را در چت‌باکس بگو؛ اعمال می‌شود و دموی تازه می‌آید. تا تایید نکنی، خروجی نهایی ساخته نمی‌شود.": "Small and fast — for judging the edit only. Ask for changes in the chat box; they are applied and a fresh demo arrives. Nothing final renders until you approve.",
  "فرست": "Send",
  "تایید — خروجی نهایی": "Approve — build the final cut",
  "دانلود MP4": "Download MP4",
  "هنوز پیامی نیست — ادیتت را بنویس.": "No messages yet — type your edit.",
  "هنوز جابی نیست.": "No jobs yet.",
  "رفرنس‌های یادگرفته‌شده": "Learned references",
  "هر ویدیوی رفرنس یک بار تحلیل می‌شود و پروفایلش برای همیشه می‌ماند — جاب بعدی با همان سبک بی‌درنگ شروع می‌شود.": "Each reference video is analysed once and its profile is kept forever — the next job starts instantly in the same style.",
  "هنوز رفرنسی تحلیل نشده — اولین جاب، اولین حافظه می‌سازد.": "No reference analysed yet — your first job builds the first memory.",
  "استفاده در جاب جدید": "Use in a new job",
  "چگالی": "density",
  "انرژی": "energy",
  "توان سیستم": "Machine power",
  "قانون خانه ۵۰٪ است — رندرها هرگز بیشتر از این مقدار CPU نمی‌گیرند.": "The house rule is 50% — renders never take more CPU than this.",
  "ذخیرهٔ توان": "Save power",
  "ترنسکریپت": "Transcription",
  "مدل بزرگ دقیق‌تر است؛ دیفالت large-v3.": "Bigger models are more accurate; the default is large-v3.",
  "برند استودیو": "Studio brand",
  "توکن‌های پایه — جاب‌ها از رفرنس بازنویسی‌اش می‌کنند.": "The base tokens — jobs override them from the reference profile.",
  "ذخیرهٔ برند": "Save brand",
  "سرویس‌های API": "API services",
  "برای عوض کردن بنویس": "type to replace",
  "کلید ذخیره شده ✓": "key saved ✓",
  "کلید ذخیره شد ✓": "key saved ✓",
  "اصلاحات ذخیره شد ✓": "corrections saved ✓",
  "ترنسکریپت تایید شد — ادامه می‌دهد": "transcript approved — carrying on",
  "تایید شد — خروجی نهایی می‌سازد": "approved — building the final cut",
  "جاب شروع شد": "job started",
  "ترنسکریپت تایید شد": "transcript approved",
  "دمو تایید شد — خروجی نهایی می‌سازد": "demo approved — building the final cut",
  "لغو شد_toast": "cancelled",
  "آپلود شروع شد…": "uploading…",
  "آپلود شد ✓": "uploaded ✓",
  "این رفرنس از قبل تحلیل شده ✓ — پروفایل موجود بی‌درنگ به‌کار می‌رود": "this reference was analysed before ✓ — the stored profile applies instantly",
  "رفرنس از حافظه انتخاب شد ✓": "reference picked from memory ✓",
  "توان روی": "power set to",
  "ذخیره شد ✓": "saved ✓",
  "برند استودیو ذخیره شد ✓": "studio brand saved ✓",
  "مدل پیش‌فرض": "default model",
  "مدل whisper": "whisper model",
  "گام": "step",
  "از ۴": "of 4"
};

  /* Word-level table for interpolated text. Deliberately small and specific:
   * units, metric names and labels. Everyday Persian function words are only
   * included where the English reads better than leaving them out. */
  const WORDS = {
  "جاب": "job",
  "جاب‌ها": "jobs",
  "اسکیل": "skill",
  "ایجنت": "agent",
  "ایجنت‌ها": "agents",
  "رندر": "render",
  "رندرها": "renders",
  "رفرنس": "reference",
  "رفرنس‌ها": "references",
  "بریف": "brief",
  "دمو": "demo",
  "ترنسکریپت": "transcript",
  "استیج": "stage",
  "استیج‌ها": "stages",
  "چت‌باکس": "chat box",
  "چت": "chat",
  "اسپاون": "spawn",
  "اکسنت": "accent",
  "اکسپورت": "export",
  "پرامپت": "prompt",
  "لوگو": "logo",
  "فرمت": "format",
  "بیت": "beat",
  "بیت‌ها": "beats",
  "برند": "brand",
  "پالت": "palette",
  "کپشن": "caption",
  "زیرنویس": "subtitle",
  "سکن": "second",
  "فریم": "frame",
  "لایه": "layer",
  "کامپوزیت": "composite",
  "پیش‌نمایش": "preview",
  "پیش‌نویس": "draft",
  "تحویل": "delivery",
  "مدل": "model",
  "کلید": "key",
  "پورت": "port",
  "پوش": "push",
  "کامیت": "commit",
  "توکن": "token",
  "فونت": "font",
  "تیزر": "teaser",
  "لایو": "live",
  "تست": "test",
  "فایل": "file",
  "فولدر": "folder",
  "تیک": "check"
};

  /* Function words and verbs. Applied only when a strong term already matched
   * the same node: alone they would turn an untranslated Persian sentence into
   * word-for-word English, which is worse than Persian. */
  const CONNECTORS = {
  "خانواده": "family",
  "می‌گیرد": "takes over",
  "می‌دهیم": "continue",
  "می‌شود": "becomes",
  "همچنان": "still",
  "می‌کند": "does",
  "نیست؛": "is missing;",
  "آماده": "ready",
  "هشدار": "warning",
  "خاموش": "off",
  "نیامد": "did not start",
  "هنگام": "while",
  "ندارد": "does not exist",
  "برای": "for",
  "نیست": "is missing",
  "روشن": "on",
  "نبود": "was missing",
  "گیرد": "takes",
  "قبول": "before",
  "بدون": "without",
  "هنوز": "still",
  "کاری": "work",
  "اگر": "if",
  "هست": "is",
  "است": "is",
  "شده": "built",
  "شود": "runs",
  "فقط": "only",
  "نشد": "not",
  "بود": "was",
  "بین": "between",
  "خود": "itself",
  "چون": "because",
  "اما": "but",
  "ولی": "but",
  "بعد": "after",
  "روی": "on",
  "این": "this",
  "هر": "per",
  "از": "of",
  "با": "with",
  "به": "to",
  "در": "in",
  "یا": "or",
  "که": "that",
  "شد": "done",
  "رد": "failed",
  "آن": "it",
  "را": "",
  "نه": "not",
  "تا": "until",
  "هم": "also",
  "و": "and",
  "则": ""
};

  const SKIP = 'script, style, code, pre, textarea, [data-no-i18n]';
  const ATTRS = ['placeholder', 'title', 'aria-label', 'alt'];
  const norm = (s) => s.replace(/\s+/g, ' ').trim();
  const toLatin = (s) => s.replace(/[۰-۹]/g, (d) => String(FA_DIGITS.indexOf(d)));
  const HAS_FA = /[؀-ۿ]/;

  const wordList = Object.keys(WORDS).sort((a, b) => b.length - a.length);
  const connectorList = Object.keys(CONNECTORS).sort((a, b) => b.length - a.length);
  const phrases = new Map(Object.entries(PHRASES).map(([k, v]) => [norm(k), v]));
  /* node → { epoch, fa, en }: fa is the Persian the node arrived with (null for
   * a node that was never Persian), en the translation it currently shows.
   * epoch expires the cache on a locale switch, so a re-walk re-decides every
   * node; en→fa restores the remembered Persian instead of leaving English. */
  const processed = new WeakMap();
  let epoch = 0;
  let writing = false;
  let locale = read();

  function read() {
    try {
      const saved = localStorage.getItem(KEY);
      if (saved === 'en' || saved === 'fa') return saved;
    } catch {
      /* private mode */
    }
    // the studio's own default is Persian — a browser locale never overrules it;
    // English is an explicit choice (the toggle) that lands in localStorage
    return 'fa';
  }

  /** Whole-string match first, then words. Returns null when nothing applies. */
  function translate(raw) {
    if (locale !== 'en' || !raw || !HAS_FA.test(raw)) return null;
    /* Pure numbers arrive in Persian digits (readouts like ۴.۳۲ or ۱۰G): there
     * is no word to look up, the only translation is the digits themselves. */
    const trimmed = norm(raw);
    if (!HAS_FA.test(trimmed.replace(/[\u06F0-\u06F9\u0660-\u0669]/g, ''))) {
      const latin = toLatin(trimmed);
      return latin === trimmed ? null : latin;
    }
    const key = norm(raw);
    if (phrases.has(key)) return toLatin(phrases.get(key));
    /* Interpolated nodes ("${fa(n)} ثانیه", "1:1 · … · فید اینستاگرام") arrive
     * as one text node, so no static key can match the whole. Cut the node at
     * everything that is not Persian (digits, Latin, punctuation) and keep
     * each maximal Persian run — words plus the spaces between them — whole;
     * when EVERY run has an exact entry, reassemble the sentence around the
     * untouched numbers and Latin words. One missing run and the node falls
     * through to the word path, so a half-known sentence is never mangled. */
    const FA_RUN = /[\u0600-\u06FF\u200c]+(?: [\u0600-\u06FF\u200c]+)*/g;
    const runs = [];
    let at = 0, m;
    while ((m = FA_RUN.exec(key))) {
      if (m.index > at) runs.push(key.slice(at, m.index));
      runs.push(m[0]);
      at = m.index + m[0].length;
    }
    if (at < key.length) runs.push(key.slice(at));
    if (runs.length > 1) {
      let ok = true;
      const parts = runs.map((s) => {
        const bare = norm(s);
        /* a Persian-digit run is a number: pass it through, toLatin catches it */
        if (!HAS_FA.test(bare.replace(/[\u06F0-\u06F9\u0660-\u0669]/g, ''))) return s;
        /* a lone word is more often a unit, a function word, or a connector
         * (بار = times, و = and); a multi-word run is a phrase. */
        const stripped = bare.replace(/[ًٍَّ]/g, '');
        const hit = bare.includes(' ')
          ? (phrases.get(bare) ?? WORDS[bare] ?? WORDS[stripped])
          : (WORDS[bare] ?? WORDS[stripped] ?? CONNECTORS[bare] ?? phrases.get(bare));
        if (hit === undefined) ok = false;
        return hit === undefined ? s : hit;
      });
      if (ok) {
        const out = toLatin(parts.join('')).replace(/\s+/g, ' ').trim();
        return out === key ? null : out;
      }
    }
    let out = key;
    let hits = 0;
    for (const w of wordList) {
      if (!out.includes(w)) continue;
      out = splitJoin(out, w, WORDS[w]);
      hits++;
    }
    if (!hits) return null;
    for (const w of connectorList) if (out.includes(w)) out = splitJoin(out, w, CONNECTORS[w]);
    out = toLatin(out).replace(/\s+/g, ' ').trim();
    return out === key ? null : out;
  }

  /* Replace a phrase only between word edges: «کار» must not rewrite «کاری».
   * Persian word edges are anything outside the letter block (and ZWNJ). */
  function splitJoin(text, word, replacement) {
    const esc = word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return text.replace(new RegExp(`(?<![؀-ۿ])${esc}(?![؀-ۿ])`, 'g'), replacement);
  }

  function setText(node) {
    const seen = processed.get(node);
    const cur = node.nodeValue;
    if (seen) {
      if (locale !== 'en') {
        /* restore only a node that currently shows OUR translation; a fresh
         * Persian rewrite (the engine re-rendered it) is left alone. */
        if (seen.fa !== null && cur === seen.en) node.nodeValue = seen.fa;
        return;
      }
      if (seen.epoch === epoch && cur === seen.en) return;
      /* the value changed underneath (the engine rewrote it): fall through
       * and translate the new text against the current dictionaries. */
    }
    const next = locale === 'en' ? translate(cur) : null;
    processed.set(node, {
      epoch,
      fa: seen && seen.fa !== null ? seen.fa : cur,
      en: next !== null ? next : seen ? seen.en : null,
    });
    if (next !== null) node.nodeValue = next;
  }

  function setAttr(el, name) {
    const raw = el.getAttribute(name);
    if (!raw) return;
    const next = translate(raw);
    if (next !== null && next !== raw) el.setAttribute(name, next);
  }

  function walk(root) {
    if (root.nodeType === Node.TEXT_NODE) {
      setText(root);
      return;
    }
    if (root.nodeType !== Node.ELEMENT_NODE && root.nodeType !== Node.DOCUMENT_FRAGMENT_NODE) return;
    const el = root.nodeType === Node.ELEMENT_NODE ? root : null;
    if (el && el.matches(SKIP)) return;
    if (el) for (const a of ATTRS) setAttr(el, a);
    const tw = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT, {
      acceptNode(n) {
        if (n.nodeType === Node.ELEMENT_NODE) {
          const e = n;
          return e.matches && e.matches(SKIP) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT;
        }
        const parent = n.parentElement;
        return parent && parent.closest(SKIP) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT;
      },
    });
    let n;
    while ((n = tw.nextNode())) {
      if (n.nodeType === Node.TEXT_NODE) setText(n);
      else for (const a of ATTRS) setAttr(n, a);
    }
  }

  function applyChrome() {
    document.documentElement.lang = locale === 'fa' ? 'fa' : 'en';
    document.documentElement.dir = locale === 'fa' ? 'rtl' : 'ltr';
    document.title = locale === 'fa' ? 'استودیوی ویدیو' : 'Video Studio';
    const btn = document.getElementById('langBtn');
    if (btn) {
      btn.textContent = locale === 'fa' ? 'English' : 'فارسی';
      btn.setAttribute('aria-label', locale === 'fa' ? 'Switch to English' : 'تغییر به فارسی');
      btn.dataset.locale = locale;
    }
    document.dispatchEvent(new CustomEvent('studio:lang', { detail: { locale } }));
  }

  function set(l) {
    const next = l === 'en' ? 'en' : 'fa';
    try {
      localStorage.setItem(KEY, next);
    } catch {
      /* private mode */
    }
    if (next !== locale && document.readyState !== 'loading') {
      /* A full re-render in the other language beats patching hundreds of
       * translated nodes: boot() applies the choice natively on reload —
       * direction, chrome and every dynamic string included. */
      location.reload();
      return;
    }
    locale = next;
    /* Nodes are cached with an epoch; bumping it makes the re-walk re-decide
     * every node (and restore the Persian on the way back to fa). */
    epoch++;
    applyChrome();
    writing = true;
    walk(document.documentElement);
    writing = false;
  }

  /* Records seen since the last frame. Batches must accumulate, not replace:
   * app.js renders several waves in one frame, and dropping an earlier batch
   * (cancelAnimationFrame + fresh records) left those nodes Persian forever. */
  const pending = [];
  let queued = null;
  const obs = new MutationObserver((records) => {
    if (writing || locale !== 'en') return;
    pending.push(...records);
    if (queued) return;
    queued = requestAnimationFrame(() => {
      queued = null;
      writing = true;
      for (const r of pending.splice(0)) {
        if (r.type === 'characterData') {
          const node = r.target;
          processed.delete(node.nodeType === Node.TEXT_NODE ? node : node.firstChild || node);
          walk(node);
        } else if (r.type === 'childList') {
          for (const n of r.addedNodes) walk(n);
          if (r.target.nodeType === Node.ELEMENT_NODE)
            for (const a of ATTRS) setAttr(r.target, a);
        } else if (r.type === 'attributes') {
          processed.delete(r.target);
          walk(r.target);
        }
      }
      writing = false;
    });
  });

  obs.observe(document.documentElement, {
    childList: true,
    subtree: true,
    characterData: true,
    attributes: true,
    attributeFilter: ATTRS,
  });

  document.addEventListener('click', (e) => {
    if (e.target.closest && e.target.closest('#langBtn')) set(locale === 'fa' ? 'en' : 'fa');
  });

  applyChrome();
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => walk(document.documentElement));
  else walk(document.documentElement);

  /* Debug handle: what would remain Persian, and why. */
  window.__i18n = {
    get locale() {
      return locale;
    },
    set,
    uncovered() {
      const left = [];
      const tw = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
      let n;
      while ((n = tw.nextNode())) {
        if (n.parentElement && n.parentElement.closest(SKIP)) continue;
        if (HAS_FA.test(n.nodeValue || '')) left.push(norm(n.nodeValue));
      }
      return [...new Set(left)];
    },
  };
})();
